style.css:
@-moz-document domain("pinterest.com") {
/* define the palette as variables for easy tweaking */
    :root {
        --nea-vanilla-bg: #FFFBF5;        /* Very light cream for main background */
        --nea-vanilla-card: #FFFFFF;      /* Pure white for the actual pins */
        --nea-chocolate-text: #4E342E;   /* Deep cocoa for dark text */
        --nea-milk-chocolate: #795548;   /* Lighter chocolate for secondary text */
        --nea-strawberry-accent: #FF85A1; /* Primary pink for buttons/notifications */
        --nea-strawberry-hover: #FCE4EC;  /* Soft pink for hover states */
        --nea-border: #EAD7BB;           /* Light brownish/cream for borders */
    }

    /* -------------------------------------------
       1. Global Backgrounds & Text
       ------------------------------------------- */
    body, 
    #HeaderContent,
    .FullPageModal__scroller,
    div[data-test-id="full-grid-container"],
    div[role="main"] {
        background-color: var(--nea-vanilla-bg) !important;
        color: var(--nea-chocolate-text) !important;
    }

    /* Typography fixes */
    h1, h2, h3, h4, h5, h6, 
    span:not(.ad-badge), p, div {
        color: var(--nea-chocolate-text) !important;
    }

    /* -------------------------------------------
       2. The Header (Vanilla with Choc Border)
       ------------------------------------------- */
    [data-test-id="header-background"],
    div[data-test-id="StandardHeader"] {
        background-color: var(--nea-vanilla-bg) !important;
        border-bottom: 2px solid var(--nea-border) !important;
        box-shadow: none !important;
    }

    /* Search Bar (Light Vanilla) */
    [data-test-id="search-box-container"] {
        background-color: var(--nea-vanilla-bg) !important;
    }

    [data-test-id="search-box-input"] {
        background-color: #F3E5DC !important; /* Lighter vanilla-choc mix */
        color: var(--nea-chocolate-text) !important;
        border: 1px solid var(--nea-border) !important;
    }

    [data-test-id="search-box-input"]::placeholder {
        color: var(--nea-milk-chocolate) !important;
        opacity: 0.8;
    }

    /* Navigation Icons (Chocolate) */
    [data-test-id="HeaderContent"] svg {
        fill: var(--nea-chocolate-text) !important;
    }
    
    /* Red 'notifications' dot -> Strawberry */
    [data-test-id="HeaderContent"] div[style*="background-color: rgb(230, 0, 35)"] {
        background-color: var(--nea-strawberry-accent) !important;
    }

    /* -------------------------------------------
       3. Buttons & Interactions (Strawberry)
       ------------------------------------------- */
    
    /* Primary Red Buttons (Save, Follow, etc.) -> Strawberry Pink */
    .red.active,
    div[style*="background-color: rgb(230, 0, 35)"],
    button[style*="background-color: rgb(230, 0, 35)"],
    [data-test-id="pdp-buy-it-button"],
    [data-test-id="board-section-follow-button"] {
        background-color: var(--nea-strawberry-accent) !important;
        color: white !important;
        transition: background-color 0.2s ease;
    }

    /* Hover effect for buttons */
    .red.active:hover,
    div[style*="background-color: rgb(230, 0, 35)"]:hover {
        background-color: #FF6687 !important; /* Slightly darker pink */
    }

    /* Standard Gray Buttons (like 'Send') -> Soft Chocolate/Cream */
    [data-test-id="base-button"],
    button[style*="background-color: rgb(239, 239, 239)"] {
        background-color: #F3E5DC !important;
        color: var(--nea-chocolate-text) !important;
    }

    [data-test-id="base-button"]:hover {
        background-color: #EAD7BB !important;
    }

    /* -------------------------------------------
       4. The Pins Grid (Card styling)
       ------------------------------------------- */
    [data-test-id="pin"] {
        background-color: var(--nea-vanilla-card) !important;
        border-radius: 20px !important;
        overflow: hidden;
        transition: transform 0.2s ease, box-shadow 0.2s ease;
        box-shadow: 0 2px 8px rgba(78, 52, 46, 0.08) !important;
    }

    /* Add border to Pins to mimic the inspiration */
    [data-test-id="pin-visual-wrapper"] {
        border: 1px solid var(--nea-border) !important;
        border-radius: 20px !important;
    }

    /* Hover effect on Pins */
    [data-test-id="pin"]:hover {
        transform: translateY(-3px);
        box-shadow: 0 6px 20px rgba(78, 52, 46, 0.15) !important;
    }

    /* Pin Titles and Descriptions (Chocolate) */
    [data-test-id="pin-title"] h2,
    [data-test-id="pin-title"] div,
    div[class*="Text"] {
        color: var(--nea-chocolate-text) !important;
    }

    /* Ad badges (Keep minor) */
    .ad-badge {
        color: var(--nea-milk-chocolate) !important;
        opacity: 0.6;
    }

    /* -------------------------------------------
       5. Scrollbars & Misc
       ------------------------------------------- */
    
    /* Neapolitan Scrollbar */
    ::-webkit-scrollbar {
        width: 12px;
    }

    ::-webkit-scrollbar-track {
        background: var(--nea-vanilla-bg);
    }

    ::-webkit-scrollbar-thumb {
        background: #D7CCC8; /* Soft chocolate-milk mix */
        border-radius: 10px;
        border: 3px solid var(--nea-vanilla-bg);
    }

    ::-webkit-scrollbar-thumb:hover {
        background: var(--nea-strawberry-accent);
    }

    /* Remove annoying blue outlines */
    *:focus {
        outline: none !important;
    }
}
